import{_ as a,C as t,o,c as d,ai as r,E as i,w as l}from"./chunks/framework.QGT6ovkH.js";const f=JSON.parse('{"title":"Review Cluster","description":"","frontmatter":{},"headers":[],"relativePath":"agents/review-cluster.md","filePath":"agents/review-cluster.md"}'),c={name:"agents/review-cluster.md"};function p(h,e,u,g,m,w){const n=t("ReviewClusterDiagram"),s=t("ClientOnly");return o(),d("div",null,[e[0]||(e[0]=r('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /opencode-team-lead/agents/review-cluster.md for this page in Markdown format</div><h1 id="review-cluster" tabindex="-1">Review Cluster <a class="header-anchor" href="#review-cluster" aria-label="Permalink to &quot;Review Cluster&quot;">​</a></h1><p>The review cluster is a 4-agent system that validates every code change before it ships. <code>review-manager</code> orchestrates three specialists (<code>requirements-reviewer</code>, <code>code-reviewer</code>, <code>security-reviewer</code>) running in parallel, then synthesizes their verdicts into a single structured result that the team-lead acts on.</p><p>The team-lead always delegates to <code>review-manager</code>. It never spawns reviewers directly.</p>',4)),i(s,null,{default:l(()=>[i(n)]),_:1}),e[1]||(e[1]=r(`<h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>team-lead</span></span>
<span class="line"><span>  └─► review-manager</span></span>
<span class="line"><span>        ├─► requirements-reviewer  (parallel)</span></span>
<span class="line"><span>        ├─► code-reviewer          (parallel)</span></span>
<span class="line"><span>        └─► security-reviewer      (parallel)</span></span>
<span class="line"><span>              ↓</span></span>
<span class="line"><span>        Arbitrate disagreements</span></span>
<span class="line"><span>              ↓</span></span>
<span class="line"><span>        Single verdict → team-lead</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><ol><li>The team-lead sends a review mission to <code>review-manager</code> with: what changed, which files, the original user requirements, and trade-offs made.</li><li><code>review-manager</code> reads enough to classify the change type and selects which reviewers to spawn.</li><li>Reviewers run in parallel — each with a self-contained prompt, no shared context between them.</li><li><code>review-manager</code> collects their verdicts, arbitrates disagreements, and returns one structured result.</li><li>The team-lead acts on the verdict.</li></ol><h2 id="the-4-agents" tabindex="-1">The 4 Agents <a class="header-anchor" href="#the-4-agents" aria-label="Permalink to &quot;The 4 Agents&quot;">​</a></h2><h3 id="review-manager" tabindex="-1">review-manager <a class="header-anchor" href="#review-manager" aria-label="Permalink to &quot;review-manager&quot;">​</a></h3><p>The review orchestrator. Its job is reviewer selection, prompt crafting, parallel execution, and verdict arbitration. It never reviews code itself — even a &quot;quick look&quot; is delegated.</p><p><strong>Mode:</strong> <code>subagent</code> — invisible to the user, only reachable via <code>task</code> from the team-lead.</p><p>When it receives a mission, it:</p><ul><li>Classifies the change type and risk level</li><li>Selects the appropriate reviewers (see selection matrix below)</li><li>Crafts a self-contained prompt for each reviewer</li><li>Launches them simultaneously</li><li>Arbitrates disagreements: requirements failures block, security concerns win ties, critical severity always wins, minor style disputes don&#39;t block</li><li>Returns the structured verdict</li></ul><p><strong>Fast path:</strong> For docs-only or formatting-only changes, <code>review-manager</code> returns APPROVED immediately without spawning any reviewers.</p><h3 id="requirements-reviewer" tabindex="-1">requirements-reviewer <a class="header-anchor" href="#requirements-reviewer" aria-label="Permalink to &quot;requirements-reviewer&quot;">​</a></h3><p>Verifies that the implementation does what the user asked. Nothing more, nothing less.</p><p><strong>Focus:</strong> functional compliance — did we build what was asked, not how well it was built.</p><p><strong>Cardinal rule:</strong> If the original user requirements are absent from the mission, returns <code>BLOCKED</code> immediately. Requirements cannot be inferred from code alone — that&#39;s guesswork, not review.</p><p>Four categories of findings:</p><ul><li><strong>Missing feature</strong> — requirement stated, not implemented at all</li><li><strong>Misinterpretation</strong> — requirement implemented differently than specified (even if &quot;better&quot;)</li><li><strong>Partial implementation</strong> — addressed but incomplete (happy path works, explicit edge case missing)</li><li><strong>Scope creep</strong> — implementation does things the user did not ask for</li></ul><p>Scope creep is a real issue. If the user asked to change X and the implementation also changed Y, it gets flagged — even if Y looks like an improvement.</p><h3 id="code-reviewer" tabindex="-1">code-reviewer <a class="header-anchor" href="#code-reviewer" aria-label="Permalink to &quot;code-reviewer&quot;">​</a></h3><p>Evaluates technical quality: logic correctness, error handling, edge cases, API design, patterns, and maintainability.</p><p><strong>Focus:</strong> is this code technically sound?</p><p><strong>Not in scope:</strong> security vulnerabilities (that&#39;s <code>security-reviewer</code>), functional compliance (that&#39;s <code>requirements-reviewer</code>).</p><p>Concrete checks on every review:</p><ul><li>Null/undefined not guarded where inputs are uncontrolled</li><li>Errors swallowed silently (empty <code>catch</code> body or generic log)</li><li>Off-by-one in loops, index access, range checks</li><li>Async errors not awaited or not caught</li><li>Functions doing too many things (single-responsibility violation)</li><li>Dead code or unreachable branches</li><li>Naming that doesn&#39;t match behavior</li><li>Inconsistent patterns vs. the rest of the codebase</li><li>Missing tests for new logic (when tests exist in the project)</li></ul><p>Style is only flagged when it degrades readability or creates inconsistency — not for its own sake.</p><h3 id="security-reviewer" tabindex="-1">security-reviewer <a class="header-anchor" href="#security-reviewer" aria-label="Permalink to &quot;security-reviewer&quot;">​</a></h3><p>Identifies vulnerabilities, misconfigurations, and data exposure risks.</p><p><strong>Focus:</strong> does this change introduce or expose a security risk?</p><p><strong>Not in scope:</strong> code quality, style, functional compliance.</p><p><strong>Seven threat categories:</strong></p><table tabindex="0"><thead><tr><th>Category</th><th>Examples</th></tr></thead><tbody><tr><td><strong>Injection</strong></td><td>SQL/NoSQL string concatenation, shell commands from user input, prompt injection, template injection</td></tr><tr><td><strong>Authentication &amp; Authorization</strong></td><td>Missing auth checks, bypassable auth, privilege escalation, insecure token handling, JWT flaws</td></tr><tr><td><strong>Data Exposure</strong></td><td>Sensitive data logged, over-fetching API responses, missing encryption at rest, stack traces to clients</td></tr><tr><td><strong>Input Validation</strong></td><td>Missing sanitization, path traversal, mass assignment, missing size limits</td></tr><tr><td><strong>Secret Handling</strong></td><td>Hardcoded credentials, secrets in env vars that get logged, private keys in repo</td></tr><tr><td><strong>Dependency &amp; Supply Chain</strong></td><td>New dependencies, unpinned versions for security-critical packages, untrusted registries</td></tr><tr><td><strong>Infrastructure Misconfigs</strong></td><td>Overly permissive IAM, public storage buckets, open ports, TLS disabled</td></tr></tbody></table><p><strong>Unconditional blocker:</strong> any critical security finding triggers BLOCKED, no exceptions, regardless of other reviewers&#39; verdicts.</p><p>For changes touching auth, session/token handling, or cryptographic operations, the security-reviewer must explicitly acknowledge the review in its output — even if no issues were found. Absence of a finding is not implicit.</p><h2 id="verdict-protocol" tabindex="-1">Verdict Protocol <a class="header-anchor" href="#verdict-protocol" aria-label="Permalink to &quot;Verdict Protocol&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Verdict</th><th>Meaning</th><th>team-lead&#39;s action</th></tr></thead><tbody><tr><td><strong>APPROVED</strong></td><td>All reviewers found no critical or major issues; requirements met; no open questions</td><td>Proceed to delivery</td></tr><tr><td><strong>CHANGES_REQUESTED</strong></td><td>Issues that can be fixed without architectural rework</td><td>Re-delegate fixes to the original producer, then request a second review</td></tr><tr><td><strong>BLOCKED</strong></td><td>Critical issue with no safe path forward, or implementation fundamentally mismatches requirements</td><td>Stop. Escalate to user with full reasoning. Do NOT fix without user input.</td></tr></tbody></table><p>When in doubt between APPROVED and CHANGES_REQUESTED, <code>review-manager</code> defaults to CHANGES_REQUESTED. The cost of a false approval is higher than the cost of an extra fix cycle.</p><p><strong>Maximum 2 review rounds.</strong> If not approved after 2 iterations, the team-lead escalates to the user rather than looping further.</p><h2 id="reviewer-selection-matrix" tabindex="-1">Reviewer Selection Matrix <a class="header-anchor" href="#reviewer-selection-matrix" aria-label="Permalink to &quot;Reviewer Selection Matrix&quot;">​</a></h2><p><code>review-manager</code> applies proportionality rules — risk overrides size:</p><table tabindex="0"><thead><tr><th>Change type</th><th>Size</th><th>Risk</th><th>Reviewers spawned</th></tr></thead><tbody><tr><td>Docs-only / formatting</td><td>any</td><td>n/a</td><td><strong>None</strong> — instant APPROVED</td></tr><tr><td>Any code change</td><td>Trivial (1–2 files, &lt;50 lines)</td><td>Low</td><td>1 combined reviewer (<code>code-reviewer</code> with requirements mandate folded in)</td></tr><tr><td>Any code change</td><td>Trivial (1–2 files, &lt;50 lines)</td><td><strong>High</strong></td><td><code>requirements-reviewer</code> + <code>security-reviewer</code> + <code>code-reviewer</code></td></tr><tr><td>Any code change</td><td>Normal (3–10 files)</td><td>Low</td><td><code>requirements-reviewer</code> + <code>code-reviewer</code> + 1 domain reviewer</td></tr><tr><td>Any code change</td><td>Normal (3–10 files)</td><td><strong>High</strong></td><td><code>requirements-reviewer</code> + <code>security-reviewer</code> + <code>code-reviewer</code> + 1 domain reviewer</td></tr><tr><td>Any code change</td><td>Large (10+ files)</td><td>Low</td><td><code>requirements-reviewer</code> + <code>code-reviewer</code> + 2 domain reviewers</td></tr><tr><td>Any code change</td><td>Large (10+ files)</td><td><strong>High</strong></td><td><code>requirements-reviewer</code> + <code>security-reviewer</code> + <code>code-reviewer</code> + 1 domain reviewer</td></tr></tbody></table><p><strong>Hard cap:</strong> never more than 3 technical reviewers. <code>requirements-reviewer</code> does not count toward this cap.</p><p><strong>High-risk patterns that always require <code>security-reviewer</code></strong> regardless of size:</p><ul><li>Auth, session, or token handling</li><li>SQL queries or ORM calls</li><li>Cryptographic operations</li><li>Permission or access control checks</li><li>Secret, credential, or API key handling</li><li>External API calls transmitting user data</li><li>Prompt injection vectors (LLM integration)</li></ul><h2 id="when-to-skip-review" tabindex="-1">When to Skip Review <a class="header-anchor" href="#when-to-skip-review" aria-label="Permalink to &quot;When to Skip Review&quot;">​</a></h2><p>The team-lead MAY skip review entirely only when <strong>all three</strong> are true:</p><ol><li>The change is documentation-only (no code, no config, no infra)</li><li>The change has no security implications</li><li>The user explicitly requested speed over thoroughness</li></ol><p>When skipping, the team-lead notes it in the report: <em>&quot;Review skipped — documentation-only change.&quot;</em></p>`,46))])}const b=a(c,[["render",p]]);export{f as __pageData,b as default};
